import * as T from '../vendor/three.module.js';
import {OrbitControls} from '../vendor/OrbitControls.js';
import {CREATURES,FAMILIES,PACK} from './catalog.mjs';
import {makeCreature,animateCreature} from './models.mjs';
const $=id=>document.getElementById(id),scene=new T.Scene();scene.background=new T.Color('#222936');scene.fog=new T.Fog('#222936',35,75);
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.outputColorSpace=T.SRGBColorSpace;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;$('viewport').append(renderer.domElement);
const camera=new T.PerspectiveCamera(38,1,.1,100),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=2;controls.maxDistance=45;controls.maxPolarAngle=Math.PI*.49;
scene.add(new T.HemisphereLight('#d5e3f3','#443443',2.8));const light=new T.DirectionalLight('#ffe2b2',4);light.position.set(-8,15,10);light.castShadow=true;light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-16,right:16,top:16,bottom:-16,far:50});light.shadow.normalBias=.04;scene.add(light);const rim=new T.DirectionalLight('#a4badf',2);rim.position.set(8,8,-10);scene.add(rim);
const ground=new T.Mesh(new T.CylinderGeometry(16,16, .2,6),new T.MeshStandardMaterial({color:'#2b3441',roughness:1}));ground.position.y=-.2;ground.receiveShadow=true;scene.add(ground);
const cast=new T.Group();scene.add(cast);let models=[],selected=null,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,last=0;let currentFamily='all',variant=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)');$('pause').textContent=paused?'Resume':'Pause';
function labelTexture(text){const c=document.createElement('canvas');c.width=128;c.height=64;const ctx=c.getContext('2d');ctx.font='500 30px sans-serif';ctx.fillStyle='#c5bda9';ctx.textAlign='center';ctx.fillText(text,64,40);return new T.CanvasTexture(c);}
function build(){for(const child of [...cast.children]){cast.remove(child);child.traverse(o=>{if(o.userData.disposable){o.geometry?.dispose();o.material?.map?.dispose();o.material?.dispose();}else if(o.userData.ownMaterial)o.material?.dispose();});}models=[];const list=CREATURES.filter(s=>currentFamily==='all'||s.family===currentFamily),cols=currentFamily==='all'?6:5;
 for(let i=0;i<list.length;i++){const spec=list[i],model=makeCreature(spec,variant),x=(i%cols-(cols-1)/2)*3,z=(Math.floor(i/cols)-(Math.ceil(list.length/cols)-1)/2)*3;model.position.set(x,0,z);model.rotation.y=.12;model.userData.anchor=[x,z];cast.add(model);models.push(model);
 const base=new T.Mesh(new T.CylinderGeometry(.98,1.03,.12,6),new T.MeshStandardMaterial({color:['#4d455a','#4a5360','#455850','#665746','#424b5c','#575054'][FAMILIES.indexOf(spec.family)],roughness:1}));base.position.set(x,-.08,z);base.receiveShadow=true;base.userData.disposable=true;cast.add(base);
 const number=new T.Mesh(new T.PlaneGeometry(.6,.3),new T.MeshBasicMaterial({map:labelTexture(String(spec.index+1).padStart(2,'0')),transparent:true,depthWrite:false}));number.rotation.x=-Math.PI/2;number.position.set(x,.005,z+.75);number.userData.disposable=true;cast.add(number);
 }
 $('status').textContent=`${list.length} neighbours · ${variant===0?'Original':variant===1?'Moonlight':'Candy'}`;renderer.domElement.dataset.count=String(models.length);renderRoster();if(selected&&list.some(s=>s.id===selected))select(selected);else overview();}
function overview(){selected=null;camera.position.set(currentFamily==='all'?20:9,currentFamily==='all'?22:11,currentFamily==='all'?27:15);controls.target.set(0,.8,currentFamily==='all'?-1.4:0);controls.update();$('type').textContent='MEET THE CAST';$('name').textContent='Nobody has to be the villain.';$('story').textContent='Click a creature to meet them. These optional story seeds suggest how even unusual neighbours could have a place in town.';$('traits').textContent='30 types · 90 palette combinations';renderRoster();}
function select(id){selected=id;const m=models.find(m=>m.userData.spec.id===id);if(!m)return;const s=m.userData.spec,[x,z]=m.userData.anchor;controls.target.set(x,s.height*.55,z);camera.position.set(x+3,s.height*.7+2,z+4.7);controls.update();$('type').textContent=s.family.toUpperCase();$('name').textContent=s.name;$('story').textContent=s.story;$('traits').textContent=`${s.motion} · ${s.palette} · ${s.height} m nominal class`;renderer.domElement.dataset.selected=id;renderRoster();}
function renderRoster(){$('roster').replaceChildren();for(const s of CREATURES.filter(s=>currentFamily==='all'||s.family===currentFamily)){const b=document.createElement('button');b.className='creature';b.setAttribute('aria-pressed',String(selected===s.id));b.innerHTML=`<span class="number">${String(s.index+1).padStart(2,'0')}</span>${s.name}<small>${s.motion}</small>`;b.onclick=()=>select(s.id);$('roster').append(b);}}
for(const family of FAMILIES){const option=document.createElement('option');option.value=family;option.textContent=family+' · 5';$('family').append(option);}
$('family').onchange=()=>{currentFamily=$('family').value;selected=null;build();};$('palette').onchange=()=>{variant=Number($('palette').value);build();};$('overview').onclick=overview;$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume':'Pause';};
$('download').onclick=()=>{const blob=new Blob([JSON.stringify(PACK,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='midnight-neighbours.halloween-pack.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const ray=new T.Raycaster(),pointer=new T.Vector2();let down;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>6)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(models,true)[0];if(hit){let o=hit.object;while(o&&!o.userData.spec)o=o.parent;if(o)select(o.userData.spec.id);}});
new ResizeObserver(()=>{const r=$('viewport').getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}).observe($('viewport'));
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;if(!document.hidden){for(const m of models)animateCreature(m,dt,$('motion').value,paused);controls.update();renderer.render(scene,camera);renderer.domElement.dataset.motion=$('motion').value;renderer.domElement.dataset.paused=String(paused);}requestAnimationFrame(frame);}build();requestAnimationFrame(frame);
